def strip_heredoc(cmd):
    # remove heredoc bodies
    out=[];skip=None
    for line in cmd.split('\n'):
        if skip is not None:
            if line.strip()==skip: skip=None
            continue
        out.append(line)
        m=re.search(r"<<-?\s*['\"]?(\w+)['\"]?",line)
        if m: skip=m.group(1)
    return '\n'.join(out)
BUILD=re.compile(r'\bant\b(?:\s+-\S+(?:\s+\S+)?)*?\s+(compileAll|compile|compileCommon|compileTests|testFast|testSystem)\b|(?:bin/)?fortress\s+compile\s+\S+|\bant\s+(\w+)')
def builds_in(cmd):
