from cls import *
def overview2(b,roles=None):
    rows=default_class(build_rows(b))
    by=collections.OrderedDict()
    for r in sorted(rows,key=lambda r:r['ts']): by.setdefault((r['label'],r['aid'][:4],r['wf'][3:7],(r['tree'] or '').replace('/home/user/','')),[]).append(r)
    for (lab,aid,wf,tree),rs in by.items():
        print(f"## {lab} {aid}/{wf} tree={tree}")
        for i,r in enumerate(rs,1):
            print(f"  {i:2d} {datetime.fromtimestamp(r['ts']).strftime('%d %H:%M:%S')} {'A ' if r['kind']=='ant' else 'L'+str(len(r['comps']))+' '} {r['cls']:3s} wall={'-' if r['wall'] is None else round(r['wall'])} {r['how']} {dict(r['marks'])} | {r['line'][:75]}")
if __name__=='__main__': overview2(sys.argv[1])
